const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Артикли</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Немецкий артикль не всегда совпадает с родом слова в русском языке. Поэтому существительные лучше всего учить вместе с артиклем.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примеры артиклей</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — стол</div>\n      <div class=\"kurss-example\">die Tür — дверь</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">das Mädchen — девочка</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Часто DER</h4>\n    <p class=\"artikuli-explain\">DER часто бывает у лиц мужского пола, дней, месяцев, времён года и некоторых слов с определёнными окончаниями.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → часто DER, например: der Computer, der Lehrer <span class=\"artikuli-note\">но не всегда</span></div>\n      <div class=\"kurss-example\">-ling → часто DER, например: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → часто DER, например: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">лица мужского пола → der Mann, der Vater</div>\n      <div class=\"kurss-example\">профессии → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">марки автомобилей → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">дни недели → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">месяцы → der August, der Dezember</div>\n      <div class=\"kurss-example\">времена года → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — мужчина</div>\n      <div class=\"kurss-example\">der Vater — отец</div>\n      <div class=\"kurss-example\">der Montag — понедельник</div>\n      <div class=\"kurss-example\">der August — август</div>\n      <div class=\"kurss-example\">der Sommer — лето</div>\n      <div class=\"kurss-example\">der Lehrer — учитель</div>\n      <div class=\"kurss-example\">der Computer — компьютер</div>\n      <div class=\"kurss-example\">der Schmetterling — бабочка</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Часто DIE</h4>\n    <p class=\"artikuli-explain\">DIE часто бывает у лиц женского пола, во множественном числе и у слов с окончаниями -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">лица женского пола → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">марки мотоциклов → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">множественное число → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">множественное число почти всегда → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — женщина</div>\n      <div class=\"kurss-example\">die Mutter — мать</div>\n      <div class=\"kurss-example\">die Wohnung — квартира</div>\n      <div class=\"kurss-example\">die Rechnung — счёт</div>\n      <div class=\"kurss-example\">die Freiheit — свобода</div>\n      <div class=\"kurss-example\">die Möglichkeit — возможность</div>\n      <div class=\"kurss-example\">die Mannschaft — команда</div>\n      <div class=\"kurss-example\">die Nation — нация</div>\n      <div class=\"kurss-example\">die Universität — университет</div>\n      <div class=\"kurss-example\">die Polizei — полиция</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Часто DAS</h4>\n    <p class=\"artikuli-explain\">DAS часто бывает у уменьшительных слов на -chen / -lein, у многих слов на -ment / -um и у глаголов, употреблённых как существительные.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">металлы → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">химические элементы → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">гостиницы → das Hotel</div>\n      <div class=\"kurss-example\">цвета как существительные → das Rot, das Blau</div>\n      <div class=\"kurss-example\">глагол как существительное → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">глаголы как существительные → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — ребёнок</div>\n      <div class=\"kurss-example\">das Mädchen — девочка</div>\n      <div class=\"kurss-example\">das Häuschen — домик</div>\n      <div class=\"kurss-example\">das Instrument — инструмент</div>\n      <div class=\"kurss-example\">das Zentrum — центр</div>\n      <div class=\"kurss-example\">das Museum — музей</div>\n      <div class=\"kurss-example\">das Essen — еда / приём пищи</div>\n      <div class=\"kurss-example\">das Lernen — учёба</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важные исключения / учить вместе с артиклем</h4>\n    <p class=\"artikuli-explain\">У некоторых слов артикль нельзя надёжно определить по окончанию или по роду в русском языке. Их лучше всего учить вместе с артиклем.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — дверь</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">die Sonne — солнце</div>\n      <div class=\"kurss-example\">der Mond — луна</div>\n      <div class=\"kurss-example\">das Mädchen — девочка</div>\n      <div class=\"kurss-example\">das Auto — автомобиль</div>\n      <div class=\"kurss-example\">der Käse — сыр</div>\n      <div class=\"kurss-example\">die Gabel — вилка</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Окончания и группы слов помогают угадать артикль, но это не стопроцентно надёжное правило. Если не уверен, учи слово вместе с артиклем.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Местоимения</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ и Dativ — формы местоимений.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — кто?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — я</div><div class=\"kurss-example\">du — ты</div><div class=\"kurss-example\">er — он</div><div class=\"kurss-example\">sie — она</div><div class=\"kurss-example\">es — оно</div><div class=\"kurss-example\">wir — мы</div><div class=\"kurss-example\">ihr — вы</div><div class=\"kurss-example\">sie — они</div><div class=\"kurss-example\">Sie — Вы (вежл.)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — кого?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — меня</div><div class=\"kurss-example\">dich — тебя</div><div class=\"kurss-example\">ihn — его (м.)</div><div class=\"kurss-example\">sie — её (ж.)</div><div class=\"kurss-example\">es — его</div><div class=\"kurss-example\">uns — нас</div><div class=\"kurss-example\">euch — вас</div><div class=\"kurss-example\">sie — их</div><div class=\"kurss-example\">Sie — Вас (вежл.)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — кому?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — мне</div><div class=\"kurss-example\">dir — тебе</div><div class=\"kurss-example\">ihm — ему</div><div class=\"kurss-example\">ihr — ей</div><div class=\"kurss-example\">uns — нам</div><div class=\"kurss-example\">euch — вам</div><div class=\"kurss-example\">ihnen — им</div><div class=\"kurss-example\">Ihnen — Вам (вежл.)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Как выбрать форму?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — подлежащее (кто действует?)</li><li><span class=\"case-red\">Akkusativ</span> — прямое дополнение (кого?)</li><li><span class=\"case-green\">Dativ</span> — косвенное дополнение (кому?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примеры</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Я вижу тебя.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Я вижу его.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Вы нам нравитесь.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Я помогаю тебе.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Я даю ему книгу.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Мы благодарим вас.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ — всегда подлежащее, а Akkusativ и Dativ — дополнения. Смотри на глагол и спрашивай: <span class=\"case-red\">кого?</span> или <span class=\"case-green\">кому?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Гласные — долгие и краткие</h3>\n            <p class=\"kurss-lesson-intro\">В немецком языке гласные бывают долгими или краткими. От этого зависит произношение слова.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Долгий гласный</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (варм) — тёплый</div><div class=\"kurss-example\">gut (гӯт) — хороший</div><div class=\"kurss-example\">Tat (та̄т) — поступок / дело</div><div class=\"kurss-example\">Flur (флӯр) — коридор / прихожая</div><div class=\"kurss-example\">Weg (ве̄к) — путь / дорога</div><div class=\"kurss-example\">Hut (хӯт) — шляпа</div><div class=\"kurss-example\">Hof (хо̄ф) — двор</div><div class=\"kurss-example\">Schlaf (шла̄ф) — сон</div></div>\n              <p>Если после гласного следует одна согласная, гласный часто произносится долго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Краткий гласный</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (пильц) — гриб</div><div class=\"kurss-example\">Wort (ворт) — слово</div><div class=\"kurss-example\">Mund (мунт) — рот</div><div class=\"kurss-example\">bald (бальт) — скоро</div><div class=\"kurss-example\">scharf (шарф) — острый</div><div class=\"kurss-example\">Feld (фельт) — поле</div><div class=\"kurss-example\">voll (фоль) — полный</div></div>\n              <p>Если после гласного следуют две или более согласных, гласный часто произносится кратко.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Окончания en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (зинген) — петь</div><div class=\"kurss-example\">tragen (тра̄ген) — нести</div><div class=\"kurss-example\">Garten (гартен) — сад</div><div class=\"kurss-example\">Vogel (фо̄гель) — птица</div><div class=\"kurss-example\">Segel (зе̄гель) — парус</div><div class=\"kurss-example\">Braten (бра̄тен) — жаркое</div><div class=\"kurss-example\">Bogen (бо̄ген) — дуга / лук</div><div class=\"kurss-example\">Spiegel (шпӣгель) — зеркало</div><div class=\"kurss-example\">Finger (фингер) — палец</div><div class=\"kurss-example\">Halter (хальтер) — держатель</div><div class=\"kurss-example\">Arbeiter (арбайтер) — рабочий</div><div class=\"kurss-example\">Häuser (хойзер) — дома</div><div class=\"kurss-example\">wieder (вӣдер) — снова</div><div class=\"kurss-example\">breiter (брайтер) — шире</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Буква h как знак долготы</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (ра̄мен) — рама / рамка</div><div class=\"kurss-example\">Ohr (о̄р) — ухо</div><div class=\"kurss-example\">Kohle (ко̄ле) — уголь</div><div class=\"kurss-example\">Zahl (ца̄ль) — число</div><div class=\"kurss-example\">ihn (ӣн) — его</div><div class=\"kurss-example\">ihm (ӣм) — ему</div><div class=\"kurss-example\">Huhn (хӯн) — курица</div><div class=\"kurss-example\">nahm (на̄м) — взял</div><div class=\"kurss-example\">nehmen (не̄мен) — брать</div><div class=\"kurss-example\">Schuh (шӯ) — ботинок / туфля</div></div>\n              <p>В некоторых словах h удлиняет предшествующий гласный. В таких случаях h обычно не произносится.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Окончания на e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (лампе) — лампа</div><div class=\"kurss-example\">Hase (ха̄зе) — заяц</div><div class=\"kurss-example\">Knabe (кна̄бе) — мальчик</div><div class=\"kurss-example\">Rabe (ра̄бе) — ворон</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Долгий i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (дӣ) — артикль «die»</div><div class=\"kurss-example\">diese (дӣзе) — эта / эти</div><div class=\"kurss-example\">wieder (вӣдер) — снова</div><div class=\"kurss-example\">Fliege (флӣге) — муха</div><div class=\"kurss-example\">Ziege (цӣге) — коза</div><div class=\"kurss-example\">Stiel (штӣль) — стебель / черенок</div><div class=\"kurss-example\">Dieb (дӣп) — вор</div><div class=\"kurss-example\">hier (хӣр) — здесь</div></div>\n              <p>Долгий i в немецком языке часто пишется как ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Двойные гласные</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (за̄ль) — зал</div><div class=\"kurss-example\">Saat (за̄т) — посев / семена</div><div class=\"kurss-example\">Staat (шта̄т) — государство</div><div class=\"kurss-example\">Beere (бе̄ре) — ягода</div><div class=\"kurss-example\">See (зе̄) — озеро / море</div><div class=\"kurss-example\">Beet (бе̄т) — грядка</div><div class=\"kurss-example\">Boot (бо̄т) — лодка</div><div class=\"kurss-example\">Moor (мо̄р) — болото</div><div class=\"kurss-example\">Moos (мо̄с) — мох</div></div>\n              <p>Двойные гласные обычно произносятся долго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (вант) — стена</div><div class=\"kurss-example\">Wände (венде) — стены</div><div class=\"kurss-example\">Vater (фа̄тер) — отец</div><div class=\"kurss-example\">Väter (фе̄тер) — отцы</div><div class=\"kurss-example\">Schrank (шранк) — шкаф</div><div class=\"kurss-example\">Schränke (шренке) — шкафы</div><div class=\"kurss-example\">Bank (банк) — скамейка / банк</div><div class=\"kurss-example\">Bänke (бенке) — скамейки</div><div class=\"kurss-example\">Tal (та̄ль) — долина</div><div class=\"kurss-example\">Täler (те̄лер) — долины</div></div>\n              <p>ä — это умлаут (перегласовка) a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Röschen (рё̄схен) — розочка</div><div class=\"kurss-example\">Ofen (о̄фен) — печь</div><div class=\"kurss-example\">Öfen (ё̄фен) — печи</div><div class=\"kurss-example\">Rock (рок) — юбка</div><div class=\"kurss-example\">Röcke (рёке) — юбки</div></div>\n              <p>ö — это умлаут (перегласовка) o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (курц) — короткий</div><div class=\"kurss-example\">kürzer (кюрцер) — короче / более короткий</div><div class=\"kurss-example\">Kunst (кунст) — искусство</div><div class=\"kurss-example\">Künste (кюнсте) — искусства</div><div class=\"kurss-example\">Mutter (мутер) — мать</div><div class=\"kurss-example\">Mütter (мютер) — матери</div></div>\n              <p>ü — это умлаут (перегласовка) u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (баум) — дерево</div><div class=\"kurss-example\">Bäume (бойме) — деревья</div><div class=\"kurss-example\">Haus (хаус) — дом</div><div class=\"kurss-example\">Häuser (хойзер) — дома</div><div class=\"kurss-example\">Strauch (штраух) — куст</div><div class=\"kurss-example\">Sträucher (штройхер) — кусты</div><div class=\"kurss-example\">Maus (маус) — мышь</div><div class=\"kurss-example\">Mäuse (мойзе) — мыши</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (хойте) — сегодня</div><div class=\"kurss-example\">Leute (лойте) — люди</div><div class=\"kurss-example\">neu (ной) — новый</div><div class=\"kurss-example\">neun (нойн) — девять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (майн) — мой</div><div class=\"kurss-example\">dein (дайн) — твой</div><div class=\"kurss-example\">sein (зайн) — его / быть</div><div class=\"kurss-example\">frei (фрай) — свободный</div><div class=\"kurss-example\">arbeiten (арбайтен) — работать</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Заметки о произношении к 2-му уроку</h4>\n              <ul class=\"kurss-summary-list\"><li>в словах ich, nicht, rechnen, zeichnen «ch» произносится мягко (примерно как «хь» в слове «хитрый»)</li><li>в словах arbeiten и zeichnen «ei» произносится как «ай»</li><li>«sp» в начале слова произносится как «шп»</li><li>в глаголе tun буква «u» произносится долго</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Итог</h4>\n              <ul class=\"kurss-summary-list\"><li>одна согласная после гласного → часто долгий гласный</li><li>две или более согласных → часто краткий гласный</li><li>h может удлинять гласный</li><li>ie часто обозначает долгий i</li><li>двойные гласные обычно долгие</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Согласные и буквенные сочетания</h3>\n            <p class=\"kurss-lesson-intro\">В немецком языке некоторые согласные и буквенные сочетания произносятся не так, как пишутся. В этом уроке собраны самые важные примеры для начинающих.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Согласные</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (ра̄т) — колесо</div><div class=\"kurss-example\">die Räder (ре̄дер) — колёса</div><div class=\"kurss-example\">Bad (ба̄т) — ванна / ванная комната</div><div class=\"kurss-example\">Bäder (бе̄дер) — ванны / ванные комнаты</div></div>\n              <p>В конце слова согласные часто произносятся не так, как пишутся (например, d звучит как «т»).</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«ch» может звучать мягко или твёрдо. В одних словах оно звучит как мягкое «хь» (как в слове «хитрый»), в других — как твёрдое русское «х».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (рехнен) — считать</div><div class=\"kurss-example\">zeichnen (цайхнен) — рисовать / чертить</div><div class=\"kurss-example\">nicht (нихт) — не</div><div class=\"kurss-example\">schlecht (шлехт) — плохой</div><div class=\"kurss-example\">mich (мих) — меня</div><div class=\"kurss-example\">dich (дих) — тебя</div><div class=\"kurss-example\">Strauch (штраух) — куст</div><div class=\"kurss-example\">noch (нох) — ещё</div><div class=\"kurss-example\">Nacht (нахт) — ночь</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» в немецком языке произносится как русское «ш».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (шӯле) — школа</div><div class=\"kurss-example\">Schüler (шю̄лер) — ученик / школьник</div><div class=\"kurss-example\">Schiff (шиф) — корабль</div><div class=\"kurss-example\">Schraube (шраубе) — винт / шуруп</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp и st в начале слова</h4>\n              <p>В начале слова или слога «sp» часто произносится как «шп», а «st» — как «шт».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (шпӣлен) — играть</div><div class=\"kurss-example\">Sprung (шпрунг) — прыжок</div><div class=\"kurss-example\">stehen (ште̄эн) — стоять</div><div class=\"kurss-example\">Stall (шталь) — хлев / конюшня</div><div class=\"kurss-example\">Stand (штант) — положение / стенд</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>«qu» в немецком языке обычно произносится как «кв».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (ква̄ль) — мучение / мука</div><div class=\"kurss-example\">Quartier (квартӣр) — жильё / квартал</div><div class=\"kurss-example\">quer (кве̄р) — поперёк</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s и z</h4>\n              <p>В начале слова «s» часто звучит как «з». Буква «z» в немецком языке звучит как русское «ц».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (за̄ген) — говорить / сказать</div><div class=\"kurss-example\">singen (зинген) — петь</div><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Zahl (ца̄ль) — число</div><div class=\"kurss-example\">Zeit (цайт) — время</div><div class=\"kurss-example\">Zink (цинк) — цинк</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>В немецком языке «v» часто произносится как «ф». В заимствованных словах оно часто звучит как русское «в».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (фа̄тер) — отец</div><div class=\"kurss-example\">von (фон) — от / из</div><div class=\"kurss-example\">viel (фӣль) — много</div><div class=\"kurss-example\">vier (фӣр) — четыре</div><div class=\"kurss-example\">Villa (вилла) — вилла</div><div class=\"kurss-example\">Klavier (клавӣр) — фортепиано / пианино</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x и y</h4>\n              <p>«x» произносится как «кс». «y» в некоторых словах произносится как «ü» (примерно как «ю» в слове «тюль»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (фе̄ликс) — Феликс</div><div class=\"kurss-example\">Axt (акст) — топор</div><div class=\"kurss-example\">Mystik (мюстик) — мистика</div><div class=\"kurss-example\">Mythe (мю̄те) — миф</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>«ß» в немецком языке произносится как «с».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (фӯс) — ступня</div><div class=\"kurss-example\">Füße (фю̄се) — ступни</div><div class=\"kurss-example\">Grüße (грю̄се) — приветы</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Итог</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ш</li><li>sp / st в начале → шп / шт</li><li>qu → кв</li><li>z → ц</li><li>v часто → ф</li><li>x → кс</li><li>ß → с</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основы глаголов</h3>\n            <p class=\"kurss-lesson-intro\">Глаголы урока 1 и их формы (спряжение)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Глаголы</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — приходить</div><div class=\"kurss-example\">gehen — идти</div><div class=\"kurss-example\">stehen — стоять</div><div class=\"kurss-example\">singen — петь</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — я прихожу</div><div class=\"kurss-example\">du kommst — ты приходишь</div><div class=\"kurss-example\">er kommt — он приходит</div><div class=\"kurss-example\">sie kommt — она приходит</div><div class=\"kurss-example\">wir kommen — мы приходим</div><div class=\"kurss-example\">ihr kommt — вы приходите</div><div class=\"kurss-example\">sie kommen — они приходят</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — я иду</div><div class=\"kurss-example\">du gehst — ты идёшь</div><div class=\"kurss-example\">er geht — он идёт</div><div class=\"kurss-example\">sie geht — она идёт</div><div class=\"kurss-example\">wir gehen — мы идём</div><div class=\"kurss-example\">ihr geht — вы идёте</div><div class=\"kurss-example\">sie gehen — они идут</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — я стою</div><div class=\"kurss-example\">du stehst — ты стоишь</div><div class=\"kurss-example\">er steht — он стоит</div><div class=\"kurss-example\">sie steht — она стоит</div><div class=\"kurss-example\">wir stehen — мы стоим</div><div class=\"kurss-example\">ihr steht — вы стоите</div><div class=\"kurss-example\">sie stehen — они стоят</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — я пою</div><div class=\"kurss-example\">du singst — ты поёшь</div><div class=\"kurss-example\">er singt — он поёт</div><div class=\"kurss-example\">sie singt — она поёт</div><div class=\"kurss-example\">wir singen — мы поём</div><div class=\"kurss-example\">ihr singt — вы поёте</div><div class=\"kurss-example\">sie singen — они поют</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Глаголы урока 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — играть</div><div class=\"kurss-example\">arbeiten — работать</div><div class=\"kurss-example\">fragen — спрашивать</div><div class=\"kurss-example\">antworten — отвечать</div><div class=\"kurss-example\">rechnen — считать</div><div class=\"kurss-example\">zeichnen — рисовать</div><div class=\"kurss-example\">tun — делать</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — я играю</div><div class=\"kurss-example\">du spielst — ты играешь</div><div class=\"kurss-example\">er spielt — он играет</div><div class=\"kurss-example\">sie spielt — она играет</div><div class=\"kurss-example\">wir spielen — мы играем</div><div class=\"kurss-example\">ihr spielt — вы играете</div><div class=\"kurss-example\">sie spielen — они играют</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — я работаю</div><div class=\"kurss-example\">du arbeitest — ты работаешь</div><div class=\"kurss-example\">er arbeitet — он работает</div><div class=\"kurss-example\">sie arbeitet — она работает</div><div class=\"kurss-example\">wir arbeiten — мы работаем</div><div class=\"kurss-example\">ihr arbeitet — вы работаете</div><div class=\"kurss-example\">sie arbeiten — они работают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — я спрашиваю</div><div class=\"kurss-example\">du fragst — ты спрашиваешь</div><div class=\"kurss-example\">er fragt — он спрашивает</div><div class=\"kurss-example\">sie fragt — она спрашивает</div><div class=\"kurss-example\">wir fragen — мы спрашиваем</div><div class=\"kurss-example\">ihr fragt — вы спрашиваете</div><div class=\"kurss-example\">sie fragen — они спрашивают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — я отвечаю</div><div class=\"kurss-example\">du antwortest — ты отвечаешь</div><div class=\"kurss-example\">er antwortet — он отвечает</div><div class=\"kurss-example\">sie antwortet — она отвечает</div><div class=\"kurss-example\">wir antworten — мы отвечаем</div><div class=\"kurss-example\">ihr antwortet — вы отвечаете</div><div class=\"kurss-example\">sie antworten — они отвечают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — я считаю</div><div class=\"kurss-example\">du rechnest — ты считаешь</div><div class=\"kurss-example\">er rechnet — он считает</div><div class=\"kurss-example\">sie rechnet — она считает</div><div class=\"kurss-example\">wir rechnen — мы считаем</div><div class=\"kurss-example\">ihr rechnet — вы считаете</div><div class=\"kurss-example\">sie rechnen — они считают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — я рисую</div><div class=\"kurss-example\">du zeichnest — ты рисуешь</div><div class=\"kurss-example\">er zeichnet — он рисует</div><div class=\"kurss-example\">sie zeichnet — она рисует</div><div class=\"kurss-example\">wir zeichnen — мы рисуем</div><div class=\"kurss-example\">ihr zeichnet — вы рисуете</div><div class=\"kurss-example\">sie zeichnen — они рисуют</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — я делаю</div><div class=\"kurss-example\">du tust — ты делаешь</div><div class=\"kurss-example\">er tut — он делает</div><div class=\"kurss-example\">sie tut — она делает</div><div class=\"kurss-example\">wir tun — мы делаем</div><div class=\"kurss-example\">ihr tut — вы делаете</div><div class=\"kurss-example\">sie tun — они делают</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Строение предложения</h3>\n            <p class=\"kurss-lesson-intro\">В вопросительном предложении глагол в немецком языке обычно стоит на первом месте.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Примеры</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Ты идёшь.</div><div class=\"kurss-example\">Kommst du? — Ты идёшь?</div><div class=\"kurss-example\">Er singt. — Он поёт.</div><div class=\"kurss-example\">Singt er? — Он поёт?</div><div class=\"kurss-example\">Stehst du? — Ты стоишь?</div><div class=\"kurss-example\">Ja, ich stehe. — Да, я стою.</div><div class=\"kurss-example\">Geht ihr? — Вы идёте?</div><div class=\"kurss-example\">Ja, wir gehen. — Да, мы идём.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Вопросы с «was»</h4>\n              <p>Если вопрос начинается с вопросительного слова, глагол в немецком языке обычно стоит сразу после вопросительного слова.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Что ты делаешь?</div><div class=\"kurss-example\">Was tut er? — Что он делает?</div><div class=\"kurss-example\">Was tut sie? — Что она делает?</div><div class=\"kurss-example\">Was tun sie? — Что они делают?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Отрицание с «nicht»</h4>\n              <p>Если отрицание «nicht» относится к глаголу, в немецком языке оно обычно стоит после глагола.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Я не играю.</div><div class=\"kurss-example\">Paul fragt nicht. — Пауль не спрашивает.</div><div class=\"kurss-example\">Er kommt nicht. — Он не идёт.</div><div class=\"kurss-example\">Sie singen nicht. — Они не поют.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Предложения из 2-го урока</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Ты играешь?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Нет, я не играю, я работаю.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Пауль не спрашивает, он работает.</div><div class=\"kurss-example\">Arbeitest du? — Ты работаешь?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Нет, я не работаю, я пою.</div><div class=\"kurss-example\">Was tut Paul? — Что делает Пауль?</div><div class=\"kurss-example\">Er spielt. — Он играет.</div><div class=\"kurss-example\">Was tut Marie? — Что делает Мари?</div><div class=\"kurss-example\">Sie singt. — Она поёт.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Пауль играет, а Мари поёт.</div><div class=\"kurss-example\">Singt ihr? — Вы поёте?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Нет, мы не поём, мы работаем.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Что делают Пауль и Мари?</div><div class=\"kurss-example\">Sie fragen. — Они спрашивают.</div><div class=\"kurss-example\">Sie antworten nicht. — Они не отвечают.</div><div class=\"kurss-example\">Wer arbeitet? — Кто работает?</div><div class=\"kurss-example\">Wir arbeiten. — Мы работаем.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Мы считаем и рисуем.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Они приходят, спрашивают, отвечают, работают, играют, поют и уходят.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Урок 2</h3>\n            <p class=\"kurss-lesson-intro\">Второй урок: диалоги, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — играть</div>\n                  <div class=\"kurss-example\">nein — нет</div>\n                  <div class=\"kurss-example\">nicht — не</div>\n                  <div class=\"kurss-example\">arbeiten — работать</div>\n                  <div class=\"kurss-example\">fragen — спрашивать</div>\n                  <div class=\"kurss-example\">was tut er? — что он делает?</div>\n                  <div class=\"kurss-example\">was tun sie? — что они делают?</div>\n                  <div class=\"kurss-example\">aber — но</div>\n                  <div class=\"kurss-example\">antworten — отвечать</div>\n                  <div class=\"kurss-example\">rechnen — считать, вычислять</div>\n                  <div class=\"kurss-example\">zeichnen — рисовать</div>\n                  <div class=\"kurss-example\">Marie — Мария</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В словах ich, nicht, rechnen, zeichnen звук ch произносится мягко, примерно как русское х в словах: химия, хитрый.</div><div class=\"kurss-example\">В словах arbeiten, zeichnen дифтонг ei произносится примерно как широкое, открытое а, за которым следует и, то есть почти как русское «ай».</div><div class=\"kurss-example\">Сочетание согласных sp произносится как шп: spielen (шпилен).</div><div class=\"kurss-example\">В глаголе tun звук u произносится долго во всех лицах.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Окончания с e</h4>\n                  <div class=\"lesson1-grammar-note\">Если основа глагола оканчивается на t, d, chn, то при спряжении перед окончаниями -st и -t стоит e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Вопросительное слово</h4>\n                  <div class=\"lesson1-grammar-note\">В вопросительных предложениях, которые начинаются с вопросительного слова, например: что? кто? который? почему? зачем? и т. п., глагол стоит сразу после вопросительного слова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Что ты делаешь?</div><div class=\"kurss-example\">Was tut er? — Что он делает?</div><div class=\"kurss-example\">Was tut sie? — Что она делает?</div><div class=\"kurss-example\">Was tun sie? — Что они делают?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Отрицание с nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Если отрицание nicht относится к глаголу, то оно стоит после глагола.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Он не приходит.</div><div class=\"kurss-example\">Sie singen nicht. — Они не поют.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 2: карточка для перевода\">\n                    <span class=\"lesson1-training-progress\">Урок 2 · Переведи: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Кто спрашивает?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Урок 6</h3>\n    <p class=\"kurss-lesson-intro\">Числительные, множественное число, умлауты и формы множественного числа существительных.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — находится, есть, лежит</div><div class=\"kurss-example\">der Bleistift (блайштифт) — карандаш</div><div class=\"kurss-example\">einige (айниге) — несколько, некоторые</div><div class=\"kurss-example\">hinlegen — положить</div><div class=\"kurss-example\">legt hin — кладёт</div><div class=\"kurss-example\">wieder (видер) — снова</div><div class=\"kurss-example\">aufmachen — открывать</div><div class=\"kurss-example\">er macht auf — он открывает</div><div class=\"kurss-example\">anspitzen (аншпицен) — точить, заострять</div><div class=\"kurss-example\">er spitzt an — он точит</div><div class=\"kurss-example\">sich setzen — садиться</div><div class=\"kurss-example\">setzt sich — садится</div><div class=\"kurss-example\">der Schlüssel (шлюсель) — ключ</div><div class=\"kurss-example\">das Fenster (фенстер) — окно</div><div class=\"kurss-example\">die Tafel (ди тафель) — доска</div><div class=\"kurss-example\">der Garten — сад</div><div class=\"kurss-example\">der Löffel — ложка</div><div class=\"kurss-example\">zählen (целен) — считать</div><div class=\"kurss-example\">die Nadel — иголка</div><div class=\"kurss-example\">was ist das — что это?</div><div class=\"kurss-example\">der Hammer — молоток</div><div class=\"kurss-example\">die Hämmer — молотки</div><div class=\"kurss-example\">der Deckel (дер декель) — крышка</div><div class=\"kurss-example\">der Teller — тарелка</div><div class=\"kurss-example\">der Wagen — повозка, телега</div><div class=\"kurss-example\">der Schlitten — сани</div><div class=\"kurss-example\">das Ding — вещь</div><div class=\"kurss-example\">die Dinge — вещи</div><div class=\"kurss-example\">wie sind die Dinge? — какие вещи?</div><div class=\"kurss-example\">voll (фол) — полный</div><div class=\"kurss-example\">leer (лер) — пустой</div><div class=\"kurss-example\">schwer (швер) — тяжёлый, трудный</div><div class=\"kurss-example\">leicht — лёгкий</div><div class=\"kurss-example\">der Eimer — ведро</div><div class=\"kurss-example\">wieviel (вифиль) — сколько</div><div class=\"kurss-example\">wieviel Nadeln — сколько иголок</div><div class=\"kurss-example\">hier (хир) — здесь</div><div class=\"kurss-example\">dort — там</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Буква ä обозначает умлаут гласного a и произносится как краткое или долгое узкое э.</div><div class=\"kurss-example\">Примеры: das Mädchen (метхен), die Bänke (ди бенке), der Vater (дер фатер), die Väter (ди фетер).</div><div class=\"kurss-example\">Буква ü обозначает умлаут гласного u. Произнося его, нужно сильно округлить губы и с округлёнными губами попытаться произнести и.</div><div class=\"kurss-example\">Примеры: fünf, der Schlüssel (шлюсель).</div><div class=\"kurss-example\">ö произносится с округлёнными губами, при этом нужно пытаться произнести э: der Löffel.</div><div class=\"kurss-example\">Удвоенная гласная буква обозначает долгий гласный: leer (лер).</div><div class=\"kurss-example\">Дифтонг eu произносится как ой: neun (нойн).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Грамматика и пояснения</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ударная приставка сложного глагола в настоящем времени отделяется от глагола и стоит в конце предложения.</div><div class=\"kurss-example\">Примеры: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Числительное «один», если оно употребляется с существительным, имеет формы всех трёх родов: в мужском роде ein, в женском роде eine, в среднем роде ein.</div><div class=\"kurss-example\">Примеры: ein Schüler — один ученик; eine Schülerin — одна ученица; ein Kind — один ребёнок.</div><div class=\"kurss-example\">Числительные: eins, zwei, drei, vier (фир), fünf, sechs (зекс), sieben (зибен), acht, neun (нойн), zehn (цен).</div><div class=\"kurss-example\">Глагол-связка в немецком языке имеет форму единственного и множественного числа: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">В русском языке в таких предложениях употребляется неизменяемое «это», и в немецком языке тоже употребляется одна форма для всех родов и чисел: das.</div><div class=\"kurss-example\">Примеры: это молоток — das ist ein Hammer; это иголка — das ist eine Nadel; это молотки — das sind Hämmer; это иголки — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — повозка и der Schlitten — сани: русское слово «сани» употребляется только во множественном числе, а в немецком языке оба слова употребляются в единственном и множественном числе.</div><div class=\"kurss-example\">Существительные мужского и среднего рода на -er, -el, -en во множественном числе часто не получают окончания.</div><div class=\"kurss-example\">Примеры: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Существительные женского рода на -el, -er во множественном числе получают -n.</div><div class=\"kurss-example\">Примеры: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Исключения: die Mutter (мать) — die Mütter (матери); die Tochter (дочь) — die Töchter (дочери).</div><div class=\"kurss-example\">У неопределённого артикля нет множественного числа: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">В повествовательном предложении сказуемое-глагол стоит на втором месте: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 6: карточка для перевода\"><span class=\"lesson1-training-progress\">Урок 6 · Переведи: 1 / 21</span><span class=\"lesson1-training-text\">Пауль берёт карандаш и рисует.</span></button><p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Урок 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, винительный падеж, sitzen, fragen и окончание -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (зицен) — сидеть</div>\n        <div class=\"kurss-example\">fragen (фраген) — спрашивать</div>\n        <div class=\"kurss-example\">der Lehrer (дер лерер) — учитель</div>\n        <div class=\"kurss-example\">gut (гут) — хорошо</div>\n        <div class=\"kurss-example\">wen (вен) — кого</div>\n        <div class=\"kurss-example\">loben — хвалить</div>\n        <div class=\"kurss-example\">der Schüler (шюлер) — ученик</div>\n        <div class=\"kurss-example\">klein — маленький</div>\n        <div class=\"kurss-example\">groß (грос) — большой</div>\n        <div class=\"kurss-example\">die Lehrerin — учительница</div>\n        <div class=\"kurss-example\">die Schülerin — ученица</div>\n        <div class=\"kurss-example\">schlecht (шлехт) — плохо</div>\n        <div class=\"kurss-example\">tadeln — ругать, порицать</div>\n        <div class=\"kurss-example\">oder (одер) — или</div>\n        <div class=\"kurss-example\">das Kind (кинт) — ребёнок</div>\n        <div class=\"kurss-example\">artig (артих) — послушный</div>\n        <div class=\"kurss-example\">die Mutter — мать</div>\n        <div class=\"kurss-example\">lieben (либен) — любить</div>\n        <div class=\"kurss-example\">der Vater (фатер) — отец</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz означает удвоенное z и произносится как z, то есть как русское ц: sitzen (зицен).</div>\n        <div class=\"kurss-example\">Буква v в немецких словах произносится как f: der Vater (фатер).</div>\n        <div class=\"kurss-example\">ß называется эсцет и произносится как русское с: groß (грос), weiß (вайс).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Именительный и винительный падежи</h4><div class=\"lesson1-grammar-note\">В русском языке именительный падеж отвечает на вопросы кто? что?, а винительный отвечает на вопросы кого? что?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В немецком языке в именительном падеже спрашивают wer? о лицах и was? о предметах.</div><div class=\"kurss-example\">В винительном падеже спрашивают wen? о лицах и was? о предметах.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Изменение артиклей в винительном падеже</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + винительный падеж</h4><div class=\"lesson1-grammar-note\">Глагол fragen в немецком языке требует винительного падежа.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Окончание -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Многие существительные женского рода образуются с помощью окончания -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Место глагола</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В повествовательном предложении глагол стоит на втором месте.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 5: карточка для перевода\"><span class=\"lesson1-training-progress\">Урок 5 · Переведи: 1 / 16</span><span class=\"lesson1-training-text\">Кого любит отец?</span></button><p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Урок 4</h3>\n            <p class=\"kurss-lesson-intro\">Винительный падеж, nehmen, hinlegen, hinausgehen и прилагательные.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (немен) — брать</div><div class=\"kurss-example\">er nimmt (нимт) — он берёт</div><div class=\"kurss-example\">der Federhalter (дер федерхальтер) — ручка для пера</div><div class=\"kurss-example\">einen Federhalter — ручку для пера</div><div class=\"kurss-example\">zeigen — показывать</div><div class=\"kurss-example\">schwarz (шварц) — чёрный</div><div class=\"kurss-example\">weiß (вайс) — белый</div><div class=\"kurss-example\">die Feder (ди федер) — перо</div><div class=\"kurss-example\">eine Feder — перо</div><div class=\"kurss-example\">spitz (шпиц) — заострённый</div><div class=\"kurss-example\">hinlegen — положить</div><div class=\"kurss-example\">legt hin — кладёт</div><div class=\"kurss-example\">das Mädchen (метхен) — девочка</div><div class=\"kurss-example\">das Messer — нож</div><div class=\"kurss-example\">ein Messer — нож</div><div class=\"kurss-example\">scharf — острый</div><div class=\"kurss-example\">stumpf (штумпф) — тупой</div><div class=\"kurss-example\">dann — потом, затем</div><div class=\"kurss-example\">hinaus — наружу</div><div class=\"kurss-example\">hinausgehen — выходить, выйти наружу</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Окончания -en, -er, -el безударные, поэтому e в этих окончаниях слышится слабо: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Буква h в немецком языке может обозначать как звук, так и долготу предыдущего гласного.</div><div class=\"kurss-example\">Если h обозначает долготу, оно не произносится как звук: nehmen (немен).</div><div class=\"kurss-example\">Если за гласным следует только один согласный, гласный произносится долго: die (ди) Feder (федер), den (ден).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Винительный падеж</h4><div class=\"lesson1-grammar-note\">В женском и среднем роде винительный падеж совпадает с именительным. Изменяется только мужской род.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Местоимения</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — мужской род</div><div class=\"kurss-example\">sie — женский род</div><div class=\"kurss-example\">es — средний род</div><div class=\"kurss-example\">во множественном числе — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Отделяемые глаголы</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Прилагательные</h4><div class=\"lesson1-grammar-note\">Если прилагательное в предложении является сказуемым, оно не изменяется ни по родам, ни по числам.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Отрицание с nicht</h4><div class=\"lesson1-grammar-note\">Если nicht отрицает прилагательное, оно стоит перед отрицаемым словом.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Существительные с окончанием -chen и -lein относятся к среднему роду: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 4: карточка для перевода\"><span class=\"lesson1-training-progress\">Урок 4 · Переведи: 1 / 16</span><span class=\"lesson1-training-text\">Девочка берёт ручку.</span></button><p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p></div></div></details>",
  "kurssLesson3": "            <h3>Урок 3</h3>\n            <p class=\"kurss-lesson-intro\">Третий урок: диалоги, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — кто</div><div class=\"kurss-example\">was — что</div><div class=\"kurss-example\">hier — здесь</div><div class=\"kurss-example\">dort — там</div><div class=\"kurss-example\">der Tisch — стол</div><div class=\"kurss-example\">ein Tisch — стол</div><div class=\"kurss-example\">die Bank — скамья</div><div class=\"kurss-example\">eine Bank — скамья</div><div class=\"kurss-example\">liegen — лежать</div><div class=\"kurss-example\">liegt hier ein Buch? — здесь есть / лежит книга?</div><div class=\"kurss-example\">das Buch — книга</div><div class=\"kurss-example\">ein Buch — книга</div><div class=\"kurss-example\">hängen — висеть</div><div class=\"kurss-example\">das Bild — картина</div><div class=\"kurss-example\">ein Bild — картина</div><div class=\"kurss-example\">die Tafel — доска</div><div class=\"kurss-example\">eine Tafel — доска</div><div class=\"kurss-example\">wie — какой, какая</div><div class=\"kurss-example\">ist — есть, является</div><div class=\"kurss-example\">dick — толстый</div><div class=\"kurss-example\">das Heft — тетрадь</div><div class=\"kurss-example\">ein Heft — тетрадь</div><div class=\"kurss-example\">dünn — тонкий</div><div class=\"kurss-example\">niedrig — низкий</div><div class=\"kurss-example\">hoch — высокий</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Долгий звук и в немецком языке обозначается сочетанием ie: liegen (лиген), hier (хир), wie (ви).</div><div class=\"kurss-example\">ck означает удвоенное k: dick (дикк).</div><div class=\"kurss-example\">В прилагательных и наречиях окончание -ig звучит как мягкое -ich: niedrig (нидрих).</div><div class=\"kurss-example\">Если после -ig следует e, то есть -ige, то g произносится как чёткий звук г: niedrige (нидриге) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Подлежащее</h4><div class=\"lesson1-grammar-note\">Подлежащее в немецком языке отвечает на вопрос wer? / was? и стоит в именительном падеже.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">С помощью wer? спрашивают о лицах.</div><div class=\"kurss-example\">С помощью was? спрашивают о предметах.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Артикли</h4><div class=\"lesson1-grammar-note\">В немецком языке у существительных 3 рода: мужской, женский и средний. Перед существительным обычно стоит служебное слово, которое называется артиклем. Это слово не переводится.</div><h5 class=\"lesson2-subtitle\">Определённый артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">мужской род — der</div><div class=\"kurss-example\">женский род — die</div><div class=\"kurss-example\">средний род — das</div><div class=\"kurss-example\">Во множественном числе определённый артикль для всех трёх родов один: die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Неопределённый артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">мужской род — ein</div><div class=\"kurss-example\">женский род — eine</div><div class=\"kurss-example\">средний род — ein</div><div class=\"kurss-example\">У неопределённого артикля нет множественного числа.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Имена собственные</h4><div class=\"lesson1-grammar-note\">Перед именами собственными артикль не употребляется.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Место глагола</h4><div class=\"lesson1-grammar-note\">В повествовательном предложении глагол стоит на втором месте.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">О предметах, которые стоят вертикально, по-немецки говорят, что предмет стоит:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">О предметах, которые находятся в горизонтальном положении, говорят, что они лежат:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Предметы могут также висеть:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 3: карточка для перевода\"><span class=\"lesson1-training-progress\">Урок 3 · Переведи: 1 / 22</span><span class=\"lesson1-training-text\">Ты считаешь?</span></button><p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p></div></div></details>",
  "kurssLesson7": "            <h3>Урок 7</h3>\n            <p class=\"kurss-lesson-intro\">Седьмой урок: повелительное наклонение, вежливая форма обращения и множественное число.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалоги / предложения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — петь</div><div class=\"kurss-example\">singe — пой</div><div class=\"kurss-example\">singt — пойте</div><div class=\"kurss-example\">singen Sie — пойте</div><div class=\"kurss-example\">das Lied (дас лит) — песня</div><div class=\"kurss-example\">Sie — Вы</div><div class=\"kurss-example\">zählen — считать</div><div class=\"kurss-example\">das Fräulein (фройлайн) — барышня</div><div class=\"kurss-example\">der Müller — мельник</div><div class=\"kurss-example\">öffnen — открывать</div><div class=\"kurss-example\">das Fenster (фенстер) — окно</div><div class=\"kurss-example\">alle — все</div><div class=\"kurss-example\">der Spiegel (шпигель) — зеркало</div><div class=\"kurss-example\">der Lappen — тряпка</div><div class=\"kurss-example\">der Spaten — лопата</div><div class=\"kurss-example\">der Besen — метла</div><div class=\"kurss-example\">die Schaufel — совок, лопатка</div><div class=\"kurss-example\">die Schüssel — миска</div><div class=\"kurss-example\">das Zimmer — комната</div><div class=\"kurss-example\">das Ufer (уфер) — берег</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp в начале слова или слога произносится как шп: der Spiegel (дер шпигель).</div><div class=\"kurss-example\">sch произносится как русское ш: die Schaufel (ди шауфель), die Schüssel (ди шюсель).</div><div class=\"kurss-example\">Дифтонг äu произносится как русское ой: das Fräulein (дас фройлайн).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Повелительное наклонение</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Повелительное наклонение во 2-м лице единственного числа образуется от формы 2-го лица единственного числа без личного окончания -st с добавлением окончания -e.</div><div class=\"kurss-example\">Примеры: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Очень часто окончание -e не употребляется, и форма повелительного наклонения становится односложной: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Повелительное наклонение во множественном числе</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Форма повелительного наклонения во 2-м лице множественного числа совпадает с формой 2-го лица множественного числа настоящего времени, но употребляется без местоимения.</div><div class=\"kurss-example\">Примеры: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Вежливая форма обращения с Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Вежливая форма обращения на «Вы» совпадает с формой 3-го лица множественного числа. Местоимение Sie пишется с большой буквы и стоит после глагола.</div><div class=\"kurss-example\">Примеры: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У глагола öffnen для облегчения произношения во 2-м и 3-м лице единственного числа и во 2-м лице множественного числа между основой и окончанием вставляется e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Упражнение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 7: карточка упражнения\"><span class=\"lesson1-training-progress\">Урок 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — спрашивать</span></button><p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть формы повелительного наклонения.</p></div></div></details>",
  "kurssLesson1": "            <h3>Урок 1</h3>\n            <p class=\"kurss-lesson-intro\">Первый урок: глаголы в настоящем времени, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Глаголы в настоящем времени</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Глаголы и их спряжение в настоящем времени.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — приходить</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>я прихожу</span><span>du</span><strong>kommst</strong><span>ты приходишь</span><span>er / sie</span><strong>kommt</strong><span>он / она приходит</span><span>wir</span><strong>kommen</strong><span>мы приходим</span><span>ihr</span><strong>kommt</strong><span>вы приходите</span><span>sie / Sie</span><strong>kommen</strong><span>они приходят / Вы приходите</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — идти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>я иду</span><span>du</span><strong>gehst</strong><span>ты идёшь</span><span>er / sie</span><strong>geht</strong><span>он / она идёт</span><span>wir</span><strong>gehen</strong><span>мы идём</span><span>ihr</span><strong>geht</strong><span>вы идёте</span><span>sie / Sie</span><strong>gehen</strong><span>они идут / Вы идёте</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — стоять</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>я стою</span><span>du</span><strong>stehst</strong><span>ты стоишь</span><span>er / sie</span><strong>steht</strong><span>он / она стоит</span><span>wir</span><strong>stehen</strong><span>мы стоим</span><span>ihr</span><strong>steht</strong><span>вы стоите</span><span>sie / Sie</span><strong>stehen</strong><span>они стоят / Вы стоите</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — петь</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>я пою</span><span>du</span><strong>singst</strong><span>ты поёшь</span><span>er / sie</span><strong>singt</strong><span>он / она поёт</span><span>wir</span><strong>singen</strong><span>мы поём</span><span>ihr</span><strong>singt</strong><span>вы поёте</span><span>sie / Sie</span><strong>singen</strong><span>они поют / Вы поёте</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Примеры</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Приблизительное произношение слов дано в скобках русскими буквами.<br>Это нужно учитывать и в следующих уроках.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (вир) — мы</div><div class=\"kurss-example\">В слове «wir» буква i произносится долго.</div><div class=\"kurss-example\">kommen (комен) — приходить</div><div class=\"kurss-example\">gehen (ге-ен) — идти</div><div class=\"kurss-example\">stehen (ште-ен) — стоять</div><div class=\"kurss-example\">singen (зинген) — петь</div><div class=\"kurss-example\">du (ду) kommst — ты приходишь</div><div class=\"kurss-example\">er (эр) kommt — он приходит</div><div class=\"kurss-example\">sie (зи) kommt — она приходит</div><div class=\"kurss-example\">wer (вер) — кто?</div><div class=\"kurss-example\">ja (я) — да</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Правильное произношение слов, записанное русскими буквами, дано в уроках.</div><div class=\"kurss-example\">Wir (вир) — мы. В слове wir звук и всегда произносится долго.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Грамматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Инфинитив</h4><div class=\"lesson1-grammar-note\">Начальная форма глагола. Обычно инфинитив оканчивается на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Окончания настоящего времени</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Отбрось <span class=\"lesson1-ending-accent\">-en</span> от начальной формы глагола и добавь окончание.</strong></p><p>Пример: kommen → komm + окончание</p><div class=\"lesson1-ending-process\" aria-label=\"Как образуются формы настоящего времени\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>начальная форма</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>отбрось <span class=\"lesson1-ending-accent\">-en</span></strong><span>остаётся основа</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>основа</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>добавь окончание</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Примеры</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Вопросительные предложения</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>В немецком вопросительном предложении глагол обычно переходит на первое место.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">По-русски:<br>Ты приходишь.<br>Ты приходишь?</div><div class=\"kurss-example\">По-немецки:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ты приходишь<br>kommst du? — ты приходишь?</div><div class=\"kurss-example\">er singt — он поёт<br>singt er? — он поёт?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Различие лиц</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — он приходит</div><div class=\"kurss-example\">sie kommt — она приходит</div><div class=\"kurss-example\">sie kommen — они приходят</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 1: тренировочная карточка\">\n                    <span class=\"lesson1-training-progress\">Урок 1 · Переведи: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Ты приходишь?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Нажми на карточку, чтобы увидеть перевод на немецкий. После ответа следующее нажатие покажет следующую карточку.</p>\n                </div>\n              </div>\n            </details>"
};

